29	    > BlockfileReader<'referred_data, K, V>
30	{
31	    pub async fn get(
32	        &'referred_data self,
33	        prefix: &str,
34	        key: K,
35	    ) -> Result<Option<V>, Box<dyn ChromaError>> {
36	        match self {
37	            BlockfileReader::MemoryBlockfileReader(reader) => reader.get(prefix, key),
38	            BlockfileReader::ArrowBlockfileReader(reader) => reader.get(prefix, key).await,
39	        }
40	    }
41	
42	    pub async fn contains(
43	        &'referred_data self,
44	        prefix: &str,
45	        key: K,
46	    ) -> Result<bool, Box<dyn ChromaError>> {
47	        match self {
48	            BlockfileReader::ArrowBlockfileReader(reader) => reader.contains(prefix, key).await,
49	            BlockfileReader::MemoryBlockfileReader(reader) => Ok(reader.contains(prefix, key)),
50	        }
51	    }
52	
53	    pub async fn get_prefix(
54	        &'referred_data self,
55	        prefix: &'referred_data str,
56	    ) -> Result<Box<dyn Iterator<Item = (K, V)> + Send + Sync + 'referred_data>, Box<dyn ChromaError>>
57	    {
58	        match self {
59	            BlockfileReader::ArrowBlockfileReader(reader) => {
60	                Ok(Box::new(reader.get_prefix(prefix).await?))
61	            }
62	            BlockfileReader::MemoryBlockfileReader(reader) => Ok(Box::new(
63	                reader
64	                    .get_range_iter(prefix..=prefix, ..)?
65	                    .map(|(_, k, v)| (k, v)),
66	            )),
67	        }
68	    }
