        match self {
            MaxScoreWriterError::Blockfile(err) => err.code(),
            MaxScoreWriterError::Reader(err) => err.code(),
            MaxScoreWriterError::SparsePosting(_) => ErrorCodes::Internal,
        }
    }
}

// ── Block splitting ──────────────────────────────────────────────────

/// Split a sorted list of `(offset, weight)` entries into posting blocks that
/// each serialize to at most `max_bytes` (and hold at most [`MAX_BLOCK_ENTRIES`]
/// entries). A single entry that exceeds `max_bytes` on its own is still
/// emitted as its own block (it cannot be split further).
fn split_into_blocks(entries: &[(u32, f32)], max_bytes: usize) -> Vec<SparsePostingBlock> {
    let mut blocks = Vec::new();
    let n = entries.len();
    let mut start = 0;
    while start < n {
        let max_end = (start + MAX_BLOCK_ENTRIES).min(n);
        // The serialized size grows monotonically with the number of entries,
        // so we can binary search for the largest chunk that still fits.
        let mut best = start + 1; // always emit at least one entry
        let mut lo = start + 1;
        let mut hi = max_end;
        while lo <= hi {
            let mid = lo + (hi - lo) / 2;
            let size = SparsePostingBlock::from_sorted_entries(&entries[start..mid])
                .expect("non-empty sorted chunk")
                .serialized_size();
            if size <= max_bytes {
                best = mid;
                lo = mid + 1;
            } else if mid == start + 1 {
                // Even a single entry does not fit; emit it regardless.
                break;
            } else {
                hi = mid - 1;
            }
        }
        blocks.push(
            SparsePostingBlock::from_sorted_entries(&entries[start..best])
                .expect("non-empty sorted chunk"),
        );
        start = best;
    }
    blocks
}

