        vectors.push((off, vec![(4u32, 0.001 * (off as f32 + 1.0))]));
    }
    let id = build(&provider, 64, &vectors).await;
    let reader = MaxScoreReader::new(
        provider
            .read::<u32, SparsePostingBlock>(BlockfileReaderOptions::new(id, "".to_string()))
            .await
            .unwrap(),
    );
    let enc = encode_u32(4);
    assert!(reader.get_posting_blocks(&enc).await.unwrap().len() > 1);
    assert!(reader.get_directory(&enc).await.unwrap().is_some());

    // Fork with a large block size and delete almost everything, leaving a
    // single-block dimension -> directory must be removed.
    let fork_writer = provider
        .write::<u32, SparsePostingBlock>(
            BlockfileWriterOptions::new("".to_string())
                .ordered_mutations()
                .fork(id),
        )
        .await
        .unwrap();
    let ms = MaxScoreWriter::new(fork_writer, Some(reader.clone())).with_block_size(1 << 16);
    for off in 0..298u32 {
        ms.delete(off, vec![4u32]).await;
    }
    let flusher = Box::pin(ms.commit()).await.unwrap();
    let id2 = flusher.id();
    Box::pin(flusher.flush()).await.unwrap();

    let reader2 = MaxScoreReader::new(
        provider
            .read::<u32, SparsePostingBlock>(BlockfileReaderOptions::new(id2, "".to_string()))
            .await
            .unwrap(),
    );
    let blocks = reader2.get_posting_blocks(&enc).await.unwrap();
    assert_eq!(blocks.len(), 1, "should collapse to a single block");
    assert!(
        reader2.get_directory(&enc).await.unwrap().is_none(),
        "directory should be removed when a dimension collapses to one block"
    );
    let res = reader2
        .query(vec![(4u32, 1.0f32)], 10, SignedRoaringBitmap::full())
        .await
        .unwrap();
    assert_eq!(res.len(), 2);
    assert!(res.iter().all(|r| r.offset == 298 || r.offset == 299));
}

