fn exhaustive(vectors: &[(u32, Vec<(u32, f32)>)], query: &[(u32, f32)], k: usize) -> Vec<(u32, f32)> {
    let mut scored: Vec<(u32, f32)> = vectors
        .iter()
        .map(|(off, v)| {
            let s: f32 = query
                .iter()
                .map(|(qd, qv)| {
                    v.iter()
                        .find(|(vd, _)| vd == qd)
                        .map(|(_, vv)| qv * vv)
                        .unwrap_or(0.0)
                })
                .sum();
            (*off, s)
        })
        .filter(|(_, s)| *s != 0.0)
        .collect();
    scored.sort_by(|a, b| b.1.total_cmp(&a.1).then(b.0.cmp(&a.0)));
    scored.truncate(k);
    scored
}

#[tokio::test]
async fn sanity_query_and_mask() {
    let (_tmp, provider) = test_arrow_blockfile_provider(8 * 1024 * 1024);
    let vectors = vec![
        (0u32, vec![(0u32, 1.0f32), (1, 1.0), (2, 0.5)]),
        (1, vec![(0, 0.5), (3, 1.0)]),
        (2, vec![(1, 0.5), (2, 1.0), (3, 0.5)]),
        (3, vec![(0, 0.8), (1, 0.8)]),
        (4, vec![(4, 1.0), (5, 1.0)]),
    ];
    let id = build(&provider, 1 << 16, &vectors).await;
    let reader = MaxScoreReader::new(
        provider
            .read::<u32, SparsePostingBlock>(BlockfileReaderOptions::new(id, "".to_string()))
            .await
            .unwrap(),
    );

    let query = vec![(0u32, 1.0f32), (1, 1.0)];
    let res = reader
        .query(query.clone(), 3, SignedRoaringBitmap::full())
        .await
        .unwrap();
    assert_eq!(res.len(), 3);
    assert_eq!(res[0].offset, 0);
    assert_eq!(res[1].offset, 3);
    // offsets 1 and 2 tie at 0.5; descending-offset tie-break puts 2 ahead.
    assert_eq!(res[2].offset, 2);

    // k == 0 -> empty
    assert!(reader
        .query(query.clone(), 0, SignedRoaringBitmap::full())
        .await
        .unwrap()
        .is_empty());
    // no matching dims -> empty
    assert!(reader
        .query(vec![(99, 1.0)], 5, SignedRoaringBitmap::full())
        .await
        .unwrap()
        .is_empty());

    // Include mask restricts to given offsets
    let mut incl = RoaringBitmap::new();
    incl.insert(3);
    let res = reader
        .query(query.clone(), 5, SignedRoaringBitmap::Include(incl))
        .await
        .unwrap();
    assert_eq!(res.len(), 1);
    assert_eq!(res[0].offset, 3);

    // Exclude mask omits offset 0
    let mut excl = RoaringBitmap::new();
    excl.insert(0);
    let res = reader
        .query(query.clone(), 5, SignedRoaringBitmap::Exclude(excl))
        .await
        .unwrap();
    assert!(res.iter().all(|r| r.offset != 0));

    // dimension ids
    let dims = reader.get_all_dimension_ids().await.unwrap();
    assert_eq!(dims, vec![0, 1, 2, 3, 4, 5]);
}

